effect.shader:
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float l = dot(src.rgb, vec3(0.299, 0.587, 0.114));
float gate = smoothstep(threshold - 0.08, threshold + 0.08, l);
float env = 0.5 + 0.5 * sin(acTime * max(speed, 0.0) * 3.14159);
vec3 outRgb = src.rgb + glowColor.rgb * gate * env * intensity;
gl_FragColor = vec4(clamp(outRgb, vec3(0.0), vec3(1.0)), src.a);
}
